CREATE TABLE IF NOT EXISTS procurement_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL,
 requirements jsonb NOT NULL, status text NOT NULL DEFAULT 'draft', revision integer NOT NULL DEFAULT 0,
 created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evaluation_criteria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, category text NOT NULL, weight numeric NOT NULL CHECK(weight>=0 AND weight<=100), description text NOT NULL, UNIQUE(event_id,category));
CREATE TABLE suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, name text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,name));
CREATE TABLE supplier_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES suppliers ON DELETE CASCADE, document_type text NOT NULL, filename text NOT NULL, mime_type text NOT NULL, storage_path text NOT NULL, extracted_text text, processing_status text NOT NULL DEFAULT 'uploaded', error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_chunks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES supplier_documents ON DELETE CASCADE, location text NOT NULL, content text NOT NULL, UNIQUE(document_id,location));
CREATE TABLE contract_terms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES suppliers ON DELETE CASCADE, category text NOT NULL, term text NOT NULL, structured_value jsonb NOT NULL, unit text NOT NULL, source_document_id uuid NOT NULL REFERENCES supplier_documents ON DELETE CASCADE, chunk_id uuid NOT NULL REFERENCES document_chunks ON DELETE CASCADE, source_location text NOT NULL, excerpt text NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), origin text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE supplier_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES suppliers ON DELETE CASCADE, metric_type text NOT NULL, value jsonb NOT NULL, unit text NOT NULL, source text NOT NULL, UNIQUE(supplier_id,metric_type));
CREATE TABLE supplier_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, supplier_id uuid NOT NULL REFERENCES suppliers ON DELETE CASCADE, criterion_scores jsonb NOT NULL, deterministic_score numeric, qualitative_assessment jsonb, UNIQUE(event_id,supplier_id));
CREATE TABLE analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, recommended_supplier_id uuid NOT NULL REFERENCES suppliers, revision integer NOT NULL, result jsonb NOT NULL, trace jsonb NOT NULL, model text NOT NULL, generated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE risks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, supplier_id uuid NOT NULL REFERENCES suppliers, analysis_id uuid NOT NULL REFERENCES analyses ON DELETE CASCADE, category text NOT NULL, severity text NOT NULL, title text NOT NULL, description text NOT NULL, mitigation text NOT NULL, evidence jsonb NOT NULL);
CREATE TABLE negotiation_opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, supplier_id uuid NOT NULL REFERENCES suppliers, analysis_id uuid NOT NULL REFERENCES analyses ON DELETE CASCADE, priority text NOT NULL, issue text NOT NULL, current_term text NOT NULL, target_term text NOT NULL, fallback_position text NOT NULL, rationale text NOT NULL, expected_impact text NOT NULL, evidence jsonb NOT NULL);
CREATE TABLE analysis_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), analysis_id uuid NOT NULL REFERENCES analyses ON DELETE CASCADE, supplier_id uuid NOT NULL REFERENCES suppliers, document_id uuid NOT NULL REFERENCES supplier_documents, term_id uuid NOT NULL REFERENCES contract_terms, source_location text NOT NULL, excerpt text NOT NULL, claim text NOT NULL, evidence_type text NOT NULL);
CREATE TABLE decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES procurement_events ON DELETE CASCADE, selected_supplier_id uuid REFERENCES suppliers, analysis_id uuid REFERENCES analyses, outcome text NOT NULL, notes text NOT NULL, negotiation_required boolean NOT NULL, decided_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid REFERENCES procurement_events ON DELETE CASCADE, event_type text NOT NULL, actor text NOT NULL DEFAULT 'local reviewer', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON suppliers(event_id);
CREATE INDEX ON contract_terms(supplier_id);
CREATE INDEX ON analyses(event_id,generated_at DESC);
CREATE INDEX ON audit_events(event_id,created_at DESC);
